const options = {
    url: `https://${authData.account_domain}/form/2/${authData.account_id}/${inputData.form_id}/allfields`,
    method: 'GET',
    headers: {
        'X-Access-Key-Id': authData.access_key_id,
        'X-Access-Key-Secret': authData.access_key_secret
    },
    params: {
        'read_only': !1,
        'system_fields': !1
    }
};
return request(options).then((response) => response.json()).then((json) => {
    logger.info(JSON.stringify(json));
    const results = json[inputData.form_id];
    var actionFields = [];
    let fieldMap = {
        DateTime: 'Datetime',
        User: 'Object',
        Boolean: 'Boolean',
        UserGroupList: 'Object',
        Number: 'Number',
        Json: 'Object',
        JSON: 'Object',
        Date: 'Date',
        StarRating: 'Number',
        Slider: 'Number',
        Checklist: 'Object',
        MultiUser: 'Object',
        Reference: 'Object'
    };
    createField = (Id, Name, Label, IsRequired = !1, Type) => {
        return {
            Id: Id,
            Name: Name,
            Label: Label,
            IsRequired: false,
            Kind: 'Field',
            Type: Type || 'String'
        }
    };
    convertFields = (inputFields) => {
        let fields = [];
        inputFields.forEach(function(field) {
            if (!field.IsSystemField && !field.ReadOnly) {
                let actionField = createField(field.Id, field.Id, field.Name, field.Required ? !0 : !1, fieldMap[field.Type]);
                if (field.Type == 'MultiUser' || field.Type == 'User') {
                    actionField['Field::Field'] = [createField('_id', '_id', 'Id', !0)];
                    actionField.IsMultiValue = field.Type == 'MultiUser'
                } else if (field.Type == 'Reference') {
                    actionField['Field::Field'] = [createField('_id', '_id', 'Id', !0)]
                } else if (field.Type == 'Multiselect' || field.Type == 'Checkbox') {
                    actionField.IsMultiValue = !0
                } else if (field.Type == 'Checklist') {
                    actionField['Field::Field'] = [createField('value', 'value', 'value', !0), createField('selected', 'selected', 'selected', !0, 'Boolean')];
                    actionField.IsMultiValue = !0
                };
                fields.push(actionField)
            }
        });
        return fields
    };
    convertTables = (tableFields) => {
        return {
            'Field::Field': [createField('_id', '_id', 'Id', !1), ...convertFields(tableFields.Fields)],
            'Id': tableFields.Id,
            'IsMultiValue': !0,
            'IsRequired': !1,
            'Kind': 'Field',
            'Label': tableFields.Name,
            'Name': `Table::${tableFields.Id}`,
            'Type': 'Object'
        }
    };
    actionFields = convertFields(results.Fields);
    if (results.Tables) {
        results.Tables.forEach((id) => {
            actionFields.push(convertTables(results[id]))
        })
    };
    return actionFields
})

